blocks.text:
The CSS
var()
function is used to insert the custom property in CSS:

@property --my-bg-color {
  syntax: "<color>";
  inherits:
  true;
  initial-value: lightgray;
}

@property --my-txt-color {

  syntax: "<color>";
  inherits: true;
  initial-value: darkblue;

  }

div {
  width: 300px;
  height: 150px;

  padding: 15px;
  background-color: var(--my-bg-color);

  color: var(--my-txt-color);
}

@property --my-bg-color {
  syntax: "<color>";
  inherits:
  true;
  initial-value: lightgray;
}

div {
  width: 300px;

  height: 150px;
  padding: 15px;
  background-color: var(--my-bg-color);

  }

.fresh {
  --my-bg-color: #ff6347;
}

.nature {
  --my-bg-color: rgb(120,
  180, 30);
}

@property --my-bg-color {
  syntax: "<color>";
