  false;
  initial-value: lightgray;
}

@property --my-bg-color {
  syntax: "<color>";
  inherits:
  true;
  initial-value: lightgray;
}

@property --startColor {
  syntax: "<color>";

    initial-value: #EADEDB;
  inherits: false;
}

@property --endColor {
  syntax:
    "<color>";
